import sys
from collections import defaultdict

def main():
    R = int(sys.stdin.readline().strip())
    C = int(sys.stdin.readline().strip())

    def preparePascal():
        nonlocal ch, R, C
        size = 2 * (R + C)
        ch = [[0] * (size + 1) for _ in range(size + 1)]
        for i in range(size + 1):
            for j in range(i + 1):
                if j == 0 or j == i:
                    ch[i][j] = 1
                else:
                    ch[i][j] = ch[i - 1][j - 1] + ch[i - 1][j]

    def readInt():
        try:
            line = sys.stdin.readline()
            return int(line.strip())
        except:
            return 0

    def readLine():
        try:
            return sys.stdin.readline().strip()
        except:
            return ""

    size = 2 * (R + C)
    preparePascal()

    x, y = 0, 0
    v1, v2 = R + C, R + C
    while v1 >= R and v2 >= R:
        if x > y:
            c = ch[v1][R] - ch[v1 - 1][R]
            o = ch[v2][R]
            y += c * o
            v1 -= 1
        else:
            c = ch[v2][R] - ch[v2 - 1][R]
            o = ch[v1][R]
            x += c * o
            v2 -= 1

    best = abs(x - y)

    cntA = [0] * (size + 1)
    cntB = [0] * (size + 1)

    str_input = readLine()
    for i in range(2 * (R + C)):
        cntA[i + 1] = cntA[i] + (1 if str_input[i] == 'A' else 0)
        cntB[i + 1] = cntB[i] + (1 if str_input[i] == 'B' else 0)

    cache = {}

    def solve(x, y, v1, v2):
        diff = abs(x - y)
        if diff - ch[v1][R] * ch[v2][R] > best:
            return 0
        key = (x, v1, v2)
        if key in cache:
            return cache[key]
        if v1 < R or v2 < R:
            sum_v = v1 + v2
            if v1 >= cntA[sum_v] and v2 >= cntB[sum_v]:
                v1_new = v1 - cntA[sum_v]
                v2_new = v2 - cntB[sum_v]
                cache[key] = ch[v1_new + v2_new][v1_new]
                return cache[key]
            else:
                cache[key] = 0
                return 0
        ans = 0
        c = str_input[v1 + v2 - 1]
        if c != 'B':
            cur = ch[v1][R] - ch[v1 - 1][R]
            other = ch[v2][R]
            ans += solve(x, y + cur * other, v1 - 1, v2)
        if c != 'A':
            cur = ch[v2][R] - ch[v2 - 1][R]
            other = ch[v1][R]
            ans += solve(x + cur * other, y, v1, v2 - 1)
        cache[key] = ans
        return ans

    result = solve(0, 0, R + C, R + C)
    print(result)

